from __future__ import annotations

from airas.core.types.paper_values import PaperValues

VALUES_TEX_FILENAME = "values.tex"
VALUES_JSON_FILENAME = "values.json"

_HEADER = (
    "% AUTO-GENERATED by the compute_paper_values tool. DO NOT EDIT.\n"
    "% verify_paper_values regenerates this file from the run outputs and\n"
    "% fails on any difference, so manual edits always surface."
)


def render_values_tex(paper_values: PaperValues) -> str:
    """Render the \\airasval macro table from computed values.

    The paper \\input's this file and writes every experimental number as
    \\airasval{key}; an undefined key renders as ??airasval:key?? instead
    of silently disappearing.
    """
    lines = [
        _HEADER,
        r"\makeatletter",
        r"\newcommand{\airasval}[1]{\@ifundefined{airasval@#1}"
        r"{\airasvalmissing{#1}}{\csname airasval@#1\endcsname}}",
        r"\newcommand{\airasvalmissing}[1]{\textbf{??airasval:\detokenize{#1}??}}",
        r"\providecommand{\unverified}[1]{#1}",
    ]
    for value in paper_values.values:
        derivation = f"{value.op}({', '.join(value.refs)})"
        if value.round is not None:
            derivation += f" round {value.round}"
        lines.append(f"% {value.key} = {derivation}")
        lines.append(
            rf"\expandafter\def\csname airasval@{value.key}\endcsname"
            rf"{{{value.display}}}"
        )
    lines.append(r"\makeatother")
    return "\n".join(lines) + "\n"
